def seed_access_roles(apps, schema_editor):
    AccessRole = apps.get_model('warehouse', 'AccessRole')
    AccountProfile = apps.get_model('warehouse', 'AccountProfile')
    viewer_permissions = [code for code in ALL_PERMISSIONS if code.endswith('.view')]
    editor_permissions = [
        code for code in ALL_PERMISSIONS
        if not code.startswith(('configuration.', 'accounts.', 'roles.', 'data_sync.'))
    ]
    definitions = [
        ('owner', '所有者', '系统最高权限，仅用于平台所有者。', ALL_PERMISSIONS, 0),
        ('admin', '管理员', '管理用户、角色、配置和全部经营数据。', ALL_PERMISSIONS, 10),
        ('editor', '编辑者', '维护经营数据、策略、计划、任务并使用 AI。', editor_permissions, 20),
        ('viewer', '阅读者', '只读查看已授权经营数据。', viewer_permissions, 30),
    ]
    roles = {}
    for code, name, description, permissions, sort_order in definitions:
        roles[code], _ = AccessRole.objects.update_or_create(
            code=code,
            defaults={
                'name': name, 'description': description, 'role_type': 'system', 'data_scope': 'all',
                'permissions': permissions, 'is_active': True, 'sort_order': sort_order,
            },
        )
    for profile in AccountProfile.objects.all():
        profile.access_role = roles['admin'] if profile.role == 'admin' else roles['editor']
        profile.save(update_fields=['access_role'])


def remove_access_roles(apps, schema_editor):
    AccessRole = apps.get_model('warehouse', 'AccessRole')
    AccessRole.objects.filter(code__in=['owner', 'admin', 'editor', 'viewer']).delete()


